From 4913d28a0aa7908d9692071afbf6e768906793e1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:20:03 +0100
Subject: [PATCH] applets/pager: transpose the desktop grid when it doesn't fit
 the panel

Desktops in one row made a pager in a vertical panel a strip of tiny
slivers, and one column did the same in a horizontal panel. The pager
now shows the grid transposed when it runs against the panel's layout.

BUG: 474114
---
 applets/pager/qml/main.qml | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/applets/pager/qml/main.qml b/applets/pager/qml/main.qml
index b4211ddbbd..f266fecb26 100644
--- a/applets/pager/qml/main.qml
+++ b/applets/pager/qml/main.qml
@@ -245,10 +245,11 @@ PlasmoidItem {
         spacing: 1
         rows: effectiveRows * effectiveColumns >= pagerModel.count ? effectiveRows : pagerModel.count
         columns: effectiveRows * effectiveColumns >= pagerModel.count ? effectiveColumns : pagerModel.count
+        flow: transposed ? Grid.TopToBottom : Grid.LeftToRight

         z: 1

-        readonly property int effectiveRows: {
+        readonly property int desktopRows: {
             if (!pagerModel.count) {
                 return 1;
             }
@@ -278,14 +279,19 @@ PlasmoidItem {
             return rows;
         }

-        readonly property int effectiveColumns: {
+        readonly property int desktopColumns: {
             if (!pagerModel.count) {
                 return 1;
             }

-            return Math.ceil(pagerModel.count / effectiveRows);
+            return Math.ceil(pagerModel.count / desktopRows);
         }

+        readonly property bool transposed: !(root.isActivityPager && Plasmoid.configuration.pagerLayout !== 0 /*No Default*/)
+            && (root.vertical ? desktopColumns > desktopRows : desktopRows > desktopColumns)
+        readonly property int effectiveRows: transposed ? desktopColumns : desktopRows
+        readonly property int effectiveColumns: transposed ? desktopRows : desktopColumns
+
         readonly property real pagerItemSizeRatio: pagerModel.pagerItemSize.width / pagerModel.pagerItemSize.height
         readonly property real widthScaleFactor: columnWidth / pagerModel.pagerItemSize.width
         readonly property real heightScaleFactor: rowHeight / pagerModel.pagerItemSize.height
-- 
